{
  "title": "include-empty-metadata-in-serialize-evaluations",
  "request": "Hey, our _serialize_evaluations utility currently drops empty metadata dicts because it filters out falsy values. Can you change it to keep the "metadata" key even when it's an empty dict?",
  "edits": [
    {
      "path": "langfuse/_client/client.py",
      "search": "if value is not None",
      "replace": "if value is not None or (key == "metadata" and isinstance(value, dict))"
    }
  ],
  "test_path": "tests/unit/test_serialize_evaluations.py",
  "test": "import pytest

from langfuse._client.client import _serialize_evaluations

class DummyEval:
    def __init__(self, name, value=None, comment=None, metadata=None, data_type=None, config_id=None):
        self.name = name
        self.value = value
        self.comment = comment
        self.metadata = metadata
        self.data_type = data_type
        self.config_id = config_id

def test_serialize_includes_empty_metadata():
    evals = [
        DummyEval(name="test", value=1, metadata={}),
        DummyEval(name="test2", value=2, metadata={"key": "val"}),
    ]
    serialized = _serialize_evaluations(evals)
    # First item should include metadata key with empty dict
    assert "metadata" in serialized[0]
    assert serialized[0]["metadata"] == {}
    # Second item should preserve its metadata
    assert serialized[1]["metadata"] == {"key": "val"}
"
